local dlc={}local paths=require"CCZombies.paths"dlc.config={manifestUrl="https://raw.githubusercontent.com/DrNightheart/CC-Zombies-Downloadable-Assets/main/maps.json",mapsFolder=nil,}local function getMapsFolder()return dlc.config.mapsFolder or paths.mapsDir()end local state={maps={},sel=1,err=nil,errTimer=0,anyDownloadable=false,}dlc._state=state dlc.onMapListChanged=nil function dlc.fetch()state.err=nil local r=http.get(dlc.config.manifestUrl)if not r then state.err="Failed to connect to server"return false end local content=r.readAll();r.close()local manifest=textutils.unserializeJSON(content)if not manifest or not manifest.maps then state.err="Invalid manifest format"return false end state.maps=manifest.maps state.sel=math.min(state.sel,math.max(1,#state.maps))state.anyDownloadable=false for _,m in ipairs(state.maps)do if dlc.canDownload(m.size or 0)then state.anyDownloadable=true break end end return true end function dlc.download(info,binary)if not fs.exists(getMapsFolder())then fs.makeDir(getMapsFolder())end local r=http.get(info.url,nil,binary)if not r then state.err="Download failed: "..(info.name or info.file)return false end local content=r.readAll();r.close()local mode=binary and"wb"or"w"local f=fs.open(getMapsFolder()..info.file,mode)if not f then state.err="Could not save file"return false end f.write(content);f.close()return true end function dlc.isInstalled(file)return fs.exists(getMapsFolder()..file)or fs.exists(file)end function dlc.canDownload(sizeKB)return fs.getFreeSpace("/")>=(sizeKB*1024)end local function centreWrite(y,text,color)local w=term.getSize()term.setCursorPos(math.max(1,math.floor((w-#text)/2)),y)term.setTextColor(color or colors.white)term.write(text)end function dlc.draw()term.setBackgroundColor(colors.black)term.clear()local w,h=term.getSize()centreWrite(2,"CC ZOMBIES  DLC",colors.red)centreWrite(3,"================",colors.gray)if#state.maps==0 then centreWrite(math.floor(h/2),"Fetching...",colors.yellow)return end if not state.anyDownloadable then term.setCursorPos(2,math.floor(h/2))term.setTextColor(colors.red)term.write("Not enough storage to download any maps.")term.setCursorPos(2,math.floor(h/2)+1)term.setTextColor(colors.gray)term.write("Free up space and try again.")term.setCursorPos(2,h-2)term.setTextColor(colors.lightGray)term.write("R - Refresh  ` - Back")return end local maxVisible=math.min(#state.maps,math.floor((h-10)/2))local scrollOffset=math.max(0,state.sel-maxVisible)for i=1,maxVisible do local idx=i+scrollOffset local m=state.maps[idx]if not m then break end local y=5+(i-1)*2 term.setCursorPos(2,y)if idx==state.sel then term.setTextColor(colors.yellow);term.write(">")else term.write(" ")end term.setCursorPos(4,y)if dlc.isInstalled(m.file)then term.setTextColor(colors.lime);term.write("[INSTALLED] ")elseif not dlc.canDownload(m.size or 0)then term.setTextColor(colors.red);term.write("[NO SPACE]  ")else term.setTextColor(colors.white);term.write("            ")end term.setTextColor(dlc.canDownload(m.size or 0)and colors.white or colors.gray)local nameStr=m.name or m.file term.write(nameStr:sub(1,w-20))local szStr=(m.size or"?").." KB"term.setCursorPos(w-#szStr,y)term.setTextColor(colors.gray)term.write(szStr)end local sel=state.maps[state.sel]if sel then local infoY=h-5 term.setCursorPos(2,infoY);term.clearLine()term.setBackgroundColor(colors.black)local desc=(sel.description and sel.description~="")and sel.description or"No description available."term.setTextColor(colors.lightGray)term.write(desc:sub(1,w-3))term.setCursorPos(2,infoY+1);term.clearLine()if sel.author then term.setTextColor(colors.gray)term.write("by "..sel.author..(sel.version and("  v"..sel.version)or""))end end if state.err then term.setCursorPos(2,h-3)term.setBackgroundColor(colors.red)term.setTextColor(colors.white)term.clearLine()term.write(" "..state.err.." ")term.setBackgroundColor(colors.black)end term.setCursorPos(2,h-1)term.setTextColor(colors.lightGray)term.write("UP/DOWN Navigate | ENTER Download/Update | R Refresh | ` Back")end function dlc.handle()local mapListChanged=false if#state.maps==0 then dlc.draw()sleep(0.3)if not dlc.fetch()then end end local running=true while running do dlc.draw()local _,k=os.pullEvent("key")if k==keys.grave then running=false elseif k==keys.up then state.sel=math.max(1,state.sel-1)elseif k==keys.down then state.sel=math.min(math.max(1,#state.maps),state.sel+1)elseif k==keys.r then state.maps={}state.anyDownloadable=false state.err=nil dlc.draw()if dlc.fetch()then state.sel=math.min(state.sel,math.max(1,#state.maps))end elseif k==keys.enter and#state.maps>0 then local m=state.maps[state.sel]if not dlc.canDownload(m.size or 0)and not dlc.isInstalled(m.file)then state.err="Not enough storage space!"dlc.draw()sleep(1.5)state.err=nil else local wasInstalled=dlc.isInstalled(m.file)dlc.draw()local w,h=term.getSize()term.setCursorPos(2,h-3)term.setBackgroundColor(colors.yellow)term.setTextColor(colors.black)term.clearLine()term.write(" Downloading "..(m.name or m.file).."... ")term.setBackgroundColor(colors.black)if dlc.download(m)then mapListChanged=true state.err=wasInstalled and("Updated: "..(m.name or m.file))or("Downloaded: "..(m.name or m.file))if dlc.onMapListChanged then dlc.onMapListChanged()end sleep(1.2)state.err=nil else sleep(2)end end end end return mapListChanged end return dlc